const DRAFT_STORAGE_KEY="pinkpanda_unsaved_workout_drafts_v1";
function readWorkoutDrafts(){try{return JSON.parse(localStorage.getItem(DRAFT_STORAGE_KEY)||"{}")}catch{return {}}}
function storeWorkoutDraft(){if(!selectedId||editingSessionId)return;try{const all=readWorkoutDrafts();all[selectedId]={sets:draft.map(s=>({kg:String(s.kg??""),reps:String(s.reps??"")})),date:$('sessionDate')?.value||new Date().toLocaleDateString('en-CA')};localStorage.setItem(DRAFT_STORAGE_KEY,JSON.stringify(all))}catch{}}
function loadWorkoutDraft(id){const saved=readWorkoutDrafts()[id];if(saved&&Array.isArray(saved.sets)&&saved.sets.length){draft=saved.sets.map(s=>({kg:String(s.kg??""),reps:String(s.reps??"")}));return saved}draft=[];return null}
function clearWorkoutDraft(id){try{const all=readWorkoutDrafts();delete all[id];localStorage.setItem(DRAFT_STORAGE_KEY,JSON.stringify(all))}catch{}}
