function fmtRest(seconds){const s=Math.max(0,Math.ceil(seconds));return `${Math.floor(s/60)}:${String(s%60).padStart(2,"0")}`}
function updateRestTimer(){if(restEndAt!==null)restRemaining=Math.max(0,Math.ceil((restEndAt-Date.now())/1000));if(restRemaining<=0&&restEndAt!==null){restRemaining=0;restEndAt=null;if(restInterval){clearInterval(restInterval);restInterval=null}const display=$("restTime");if(display)display.textContent="Klaar!";const start=$("restStart");if(start)start.textContent="Start";return}const display=$("restTime");if(display)display.textContent=fmtRest(restRemaining);const start=$("restStart");if(start)start.textContent=restEndAt!==null?"Pauze":"Start";}
function bindRestTimer(){const choice=$("restDuration");if(!choice)return;choice.value=String(restDuration);updateRestTimer();choice.onchange=()=>{restDuration=Number(choice.value)||90;restRemaining=restDuration;restEndAt=null;if(restInterval){clearInterval(restInterval);restInterval=null}updateRestTimer()};$("restStart").onclick=()=>{if(restEndAt!==null){restRemaining=Math.max(0,Math.ceil((restEndAt-Date.now())/1000));restEndAt=null;if(restInterval){clearInterval(restInterval);restInterval=null}updateRestTimer();return}if(restRemaining<=0)restRemaining=restDuration;restEndAt=Date.now()+restRemaining*1000;if(restInterval)clearInterval(restInterval);restInterval=setInterval(updateRestTimer,250);updateRestTimer()};$("restReset").onclick=()=>{restEndAt=null;restRemaining=restDuration;if(restInterval){clearInterval(restInterval);restInterval=null}updateRestTimer()};}
