function applyTheme(id){const t=themes.find(x=>x.id===id)||themes[0];const mix=(a,b)=>{const A=a.match(/\w\w/g).map(v=>parseInt(v,16)),B=b.match(/\w\w/g).map(v=>parseInt(v,16));return '#'+A.map((v,i)=>Math.round(v*.72+B[i]*.28).toString(16).padStart(2,'0')).join('')};document.documentElement.style.setProperty('--bg',t.bg);document.documentElement.style.setProperty('--surface-glow',t.glow);document.documentElement.style.setProperty('--accent',t.accent);document.documentElement.style.setProperty('--accent2',t.accent2);document.documentElement.style.setProperty('--panel',mix(t.bg,t.glow));document.documentElement.style.setProperty('--panel2',mix(t.bg,t.accent));document.documentElement.style.setProperty('--line',mix(t.bg,t.accent));document.documentElement.style.setProperty('--text','#fff8fc');document.documentElement.style.setProperty('--muted',mix('#d0a9c4',t.accent2));document.querySelector('meta[name="theme-color"]')?.setAttribute('content',t.accent);document.body.dataset.theme=t.id;localStorage.setItem('pinkpanda_theme',t.id);}
function themeOwnership(){let owned;try{owned=JSON.parse(localStorage.getItem('pinkpanda_owned_themes')||'["pink"]')}catch(e){owned=['pink']}if(!Array.isArray(owned))owned=['pink'];if(!owned.includes('pink'))owned.unshift('pink');localStorage.setItem('pinkpanda_owned_themes',JSON.stringify(owned));return owned}
function renderSettings(){const root=$('settingsView');const current=localStorage.getItem('pinkpanda_theme')||'pink';const owned=themeOwnership();root.innerHTML=`<div class="panel"><div class="eyebrow">Maak het helemaal van jou</div><h2 class="selected-title">⚙️ Instellingen</h2><p class="settings-intro">Ontgrendel een kleurthema met je verdiende muntjes. Elke kleur kost 15 muntjes, behalve Goud: 30 muntjes. Roze is altijd gratis en blijft de standaardkleur.</p><h3 class="section-title">🎨 Achtergrondkleuren</h3><div class="theme-grid">${themes.map(t=>{const has=owned.includes(t.id),price=t.id==='gold'?30:15;return `<button class="theme-option ${t.id===current?'selected':''} ${has?'':'locked'}" data-theme-choice="${t.id}" aria-pressed="${t.id===current}"><span class="theme-swatch" style="background:radial-gradient(circle at 30% 25%,${t.accent2},${t.glow} 70%,${t.bg})"></span><span><strong>${t.name}</strong><small>${t.desc}</small><span class="theme-price">${has?(t.id===current?'✓ Actief':'✓ Ontgrendeld'):`🔒 ${price} ${coinIcon()}`}</span></span>${t.id===current?'<span style="margin-left:auto">✓</span>':(!has?'<span style="margin-left:auto">🔒</span>':'')}</button>`}).join('')}</div><div class="settings-feature"><h3>🐼 Panda-peptalk</h3><p id="settingsQuote">${motivationQuotes[Math.floor(Math.random()*motivationQuotes.length)]}</p><div class="settings-actions"><button class="primary small" id="newQuote">Geef me motivatie ✨</button><button class="secondary small" id="resetTheme">Terug naar roze 💗</button></div></div><div class="settings-feature" id="backupFeature"><h3>💾 Back-up van je gegevens</h3><p>Bewaar je trainingen, oefeningen, notities, kalender, kleuren, panda’s én progressiefoto’s in één bestand. Zet het bestand bijvoorbeeld in Google Drive, zodat je het op een nieuw toestel kunt terugzetten.</p><p id="lastBackupInfo">${formatLastBackup()}</p><div class="settings-actions"><button class="primary small" id="makeBackup">Back-up maken ⬇️</button><button class="secondary small" id="chooseBackup">Back-up terugzetten ⬆️</button><input id="backupFileInput" type="file" accept="application/json,.json" hidden></div><p class="notice">Bij terugzetten worden de huidige gegevens op dit toestel vervangen door de gegevens uit het gekozen back-upbestand.</p></div></div>`;
 root.querySelectorAll('[data-theme-choice]').forEach(b=>b.onclick=()=>{const id=b.dataset.themeChoice;let owned=themeOwnership();if(!owned.includes(id)){const price=id==='gold'?30:15;if((Number(data.coins)||0)<price){alert(`Je hebt ${price} muntjes nodig om deze kleur te ontgrendelen. Je hebt er ${Number(data.coins)||0}.`);return;}data.coins-=price;persist();owned.push(id);localStorage.setItem('pinkpanda_owned_themes',JSON.stringify(owned));$('coinCount').textContent=Number(data.coins).toLocaleString('nl-BE');}applyTheme(id);renderSettings()});$('newQuote').onclick=()=>{$('settingsQuote').textContent=motivationQuotes[Math.floor(Math.random()*motivationQuotes.length)]};$('resetTheme').onclick=()=>{applyTheme('pink');renderSettings()};
 $('makeBackup').onclick=makeBackupFile;
 $('chooseBackup').onclick=()=>$('backupFileInput').click();
 $('backupFileInput').onchange=restoreBackupFile;
}
const LAST_BACKUP_KEY='pinkpanda_last_backup_v1';
function formatLastBackup(){const value=localStorage.getItem(LAST_BACKUP_KEY);if(!value)return 'Nog geen back-up gemaakt op dit toestel.';const d=new Date(value);return 'Laatst gemaakte back-up: '+(Number.isNaN(d.getTime())?value:d.toLocaleString('nl-BE'));}
function makeBackupFile(){
 try{
  const createdAt=new Date().toISOString();localStorage.setItem(LAST_BACKUP_KEY,createdAt);
  const entries=[];for(let i=0;i<localStorage.length;i++){const key=localStorage.key(i);if(key!==null)entries.push([key,localStorage.getItem(key)]);}
  const backup={format:'PinkPandaProgression-backup',version:1,createdAt,entries};
  const blob=new Blob([JSON.stringify(backup)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='PinkPandaProgression_backup_'+createdAt.slice(0,10)+'.json';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);
  const info=$('lastBackupInfo');if(info)info.textContent=formatLastBackup();
 }catch(err){alert('De back-up kon niet worden gemaakt. Controleer of er voldoende opslagruimte beschikbaar is.');}
}
function restoreBackupFile(event){
 const file=event.target.files&&event.target.files[0];if(!file)return;
 const reader=new FileReader();reader.onload=()=>{
  try{
   const backup=JSON.parse(String(reader.result||''));
   if(!backup||backup.format!=='PinkPandaProgression-backup'||backup.version!==1||!Array.isArray(backup.entries)||!backup.entries.every(item=>Array.isArray(item)&&item.length===2&&typeof item[0]==='string'&&(typeof item[1]==='string'||item[1]===null)))throw new Error('invalid backup');
   if(!confirm('Weet je zeker dat je deze back-up wilt terugzetten? Alle huidige gegevens in deze browser worden vervangen door de gegevens uit het back-upbestand. Maak eventueel eerst een back-up van de huidige gegevens.')){event.target.value='';return;}
   localStorage.clear();for(const [key,value] of backup.entries){if(value!==null)localStorage.setItem(key,value);}
   if(backup.createdAt)localStorage.setItem(LAST_BACKUP_KEY,backup.createdAt);
   alert('Back-up teruggezet. De app wordt opnieuw geladen.');window.location.reload();
  }catch(err){alert('Dit bestand lijkt geen geldige PinkPandaProgression-back-up te zijn. Je huidige gegevens zijn niet aangepast.');event.target.value='';}
 };reader.onerror=()=>{alert('Het back-upbestand kon niet worden gelezen.');event.target.value='';};reader.readAsText(file);
}
