function renderMotivator(){const p=activePanda();const img=$("pandaMotivator");const quote=$("pandaQuote");if(img){img.hidden=true;img.onerror=()=>{img.hidden=true;};img.onload=()=>{img.hidden=false;};img.src=`./pandas/motivator/${p.id}.jpg`;img.alt=p.name;}if(quote){const quotes=[p.quote,"Elke rep brengt je dichter bij je doel. Jij kan dit! 💪","Kleine stappen, grote gains. Panda trots op jou! 🐼","Ook op een mindere dag is opdagen winst. 💗","Je hoeft niet sneller te gaan dan gisteren; blijf gewoon vooruitgaan. 🌱","Eén set tegelijk. Jij bouwt aan iets sterks! 💪","Je bent sterker dan het stemmetje dat zegt dat je moet stoppen. 🔥","Niet elke training is top, maar elke training telt. 🐼","Focus op je eigen vooruitgang, niet op die van een ander. ✨","Begin waar je bent. Gebruik wat je hebt. Doe wat je kan. 💗","Je doel wordt haalbaar door de kleine keuzes die je vandaag maakt. 🎯","Adem in, pak die halter, en geef jezelf een kans. 🏋️","Rust nemen is slim; opgeven hoeft niet. 💖","Jouw inzet telt, zelfs als niemand anders het ziet. 🌟","Maak jezelf trots, herhaling na herhaling. 👑","Elke training is een investering in jezelf. 💪","Je hoeft alleen jezelf van gisteren te verslaan. 🐼","Blijf geduldig: groei gebeurt niet in één dag. 🌱","Vandaag is een nieuwe kans om sterker te worden. 🔥","Kracht begint met komen opdagen. Jij bent er! ✨"];quote.innerHTML=`${esc(quotes[Math.floor(Math.random()*quotes.length)])}<small>🐼 ${esc(p.name)} moedigt je aan</small>`;}}
function openCharacterPreview(src,alt){const modal=$("characterPreview");const image=$("characterPreviewImage");if(!modal||!image)return;image.src=src;image.alt=alt||"Panda-karakter";modal.classList.add("open");modal.setAttribute("aria-hidden","false");}
function closeCharacterPreview(){const modal=$("characterPreview");if(!modal)return;modal.classList.remove("open");modal.setAttribute("aria-hidden","true");$("characterPreviewImage").src="";}
function renderShop(){const owned=data.ownedPandas;$("shopView").innerHTML=`<div class="panel"><div class="topline"><div><div class="eyebrow">Verzamel ze allemaal</div><h2 class="selected-title">🐼 Panda Shop</h2><p class="muted">Verdien 1 muntje wanneer je een oefeningstraining opslaat. Kies een panda die jou motiveert op het tabblad Oefeningen.</p></div><div class="coin-count">${coinIcon()}${Number(data.coins).toLocaleString('nl-BE')}</div></div><div class="shop-intro">De eerste panda is gratis. De prijzen zijn uniek en oplopend. Train regelmatig en ook de zeldzaamste panda wordt haalbaar!</div><div class="character-grid">${pandas.map(p=>{const has=owned.includes(p.id),active=data.activePanda===p.id;return `<article class="panda-card ${has?'owned':''}">${pandaArt(p)}<h3>${esc(p.name)}</h3><p>${esc(p.desc)}</p><div class="panda-price">${p.price===0?'Gratis':`${coinIcon()} ${p.price.toLocaleString('nl-BE')}`}</div>${has?`<div class="owned-tag">${active?'✓ Jouw actieve panda':'✓ In jouw collectie'}</div><button class="${active?'secondary':'primary'} small" data-select-panda="${p.id}" ${active?'disabled':''}>${active?'Geselecteerd':'Kies als motivator'}</button>`:`<button class="primary small" data-buy-panda="${p.id}" ${data.coins<p.price?'disabled':''}>${data.coins<p.price?'Nog '+(p.price-data.coins)+' coins nodig':'Koop panda'}</button>`}</article>`}).join('')}</div></div>`;
 $("shopView").querySelectorAll(".panda-face img").forEach(img=>{img.addEventListener("click",()=>openCharacterPreview(img.src,img.alt));img.tabIndex=0;img.setAttribute("role","button");img.setAttribute("aria-label",`Bekijk ${img.alt} groter`);img.addEventListener("keydown",e=>{if(e.key==="Enter"||e.key===" "){e.preventDefault();openCharacterPreview(img.src,img.alt);}})});
 $("shopView").querySelectorAll('[data-buy-panda]').forEach(b=>b.onclick=()=>{const p=pandas.find(x=>x.id===b.dataset.buyPanda);if(!p||data.ownedPandas.includes(p.id)||data.coins<p.price)return;data.coins-=p.price;data.ownedPandas.push(p.id);persist();updateCoins();renderShop();renderMotivator();});
 $("shopView").querySelectorAll('[data-select-panda]').forEach(b=>b.onclick=()=>{if(!data.ownedPandas.includes(b.dataset.selectPanda))return;data.activePanda=b.dataset.selectPanda;persist();renderShop();renderMotivator();renderWorkout();});}
function switchTab(tab){activeTab=['shop','photos','settings','calendar'].includes(tab)?tab:'exercises';document.querySelectorAll('.tab-btn').forEach(b=>b.classList.toggle('active',b.dataset.tab===activeTab));document.querySelectorAll('.view').forEach(v=>v.classList.remove('active'));$(({shop:'shopView',photos:'photosView',settings:'settingsView',calendar:'calendarView',exercises:'exerciseView'})[activeTab]).classList.add('active');if(activeTab==='shop')renderShop();else if(activeTab==='photos')renderPhotos();else if(activeTab==='settings')renderSettings();else if(activeTab==='calendar')renderCalendar();else{renderMotivator();renderList();renderWorkout();}window.scrollTo({top:0,behavior:'smooth'})}
function localISODate(d=new Date()){const y=d.getFullYear(),m=String(d.getMonth()+1).padStart(2,'0'),day=String(d.getDate()).padStart(2,'0');return `${y}-${m}-${day}`}
let calendarMonth=new Date();
function renderCalendar(){
 const root=$("calendarView");if(!root)return;
 const year=calendarMonth.getFullYear(),month=calendarMonth.getMonth(),first=new Date(year,month,1),daysInMonth=new Date(year,month+1,0).getDate(),offset=(first.getDay()+6)%7;
 const monthName=calendarMonth.toLocaleDateString('nl-BE',{month:'long',year:'numeric'});
 const entries=[...data.trainingDays].sort((a,b)=>b.date.localeCompare(a.date));
 const workoutDates=new Set((data.sessions||[]).map(x=>x.date));
 const hiddenWorkoutDates=new Set(data.calendarHiddenWorkoutDates||[]);
 const byDate={};entries.forEach(x=>{byDate[x.date]=x.training});
 const weekdays=['Ma','Di','Wo','Do','Vr','Za','Zo'];
 let cells='';for(let i=0;i<offset;i++)cells+='<div class="calendar-day empty"></div>';
 for(let day=1;day<=daysInMonth;day++){const date=`${year}-${String(month+1).padStart(2,'0')}-${String(day).padStart(2,'0')}`;const showWorkoutMarker=workoutDates.has(date)&&!hiddenWorkoutDates.has(date);const trained=Boolean(byDate[date])||showWorkoutMarker;const training=byDate[date]||(showWorkoutMarker?'Training opgeslagen':'');cells+=`<button type="button" class="calendar-day ${trained?'trained':''} ${date===localISODate()?'today':''}" data-calendar-date="${date}" aria-label="${date}${training?': '+esc(training):': geen training geregistreerd'}"><span class="day-number">${day}</span>${trained?`<span>💪</span><span class="day-training">${esc(training)}</span>`:'<span class="day-training">—</span>'}</button>`}
 const motivator=activePanda();
 root.innerHTML=`<div class="panel calendar-panel"><div class="calendar-prompt"><img src="./pandas/motivator/${motivator.id}.jpg" alt="${esc(motivator.name)}" onerror="this.style.display='none'"><div class="calendar-prompt-content"><div class="calendar-speech">Wat heb je vandaag getraint?</div><label for="trainingDescription">Vertel het aan ${esc(motivator.name)}:</label><input id="trainingDescription" maxlength="120" placeholder="Bijv. Borst en tricep, rug en bicep…"></div></div><div class="calendar-save-top"><button class="primary" id="saveTrainingDay">Training opslaan</button></div><div class="eyebrow">Jouw consistentie</div><h2 class="selected-title">🗓️ Trainingskalender</h2><p class="muted">Klik op een dag om de datum te selecteren. Je kunt ook een training van een eerdere dag toevoegen.</p><div class="calendar-head"><button class="secondary small" id="calendarPrev">← Vorige</button><h3 style="margin:0;text-transform:capitalize">${esc(monthName)}</h3><button class="secondary small" id="calendarNext">Volgende →</button></div><div class="calendar-grid">${weekdays.map(d=>`<div class="calendar-weekday">${d}</div>`).join('')}${cells}</div><div class="calendar-form"><div class="wide"><label for="trainingDate">Geselecteerde datum</label><input id="trainingDate" type="date" value="${localISODate()}" required></div><div class="wide muted" id="calendarStatus" aria-live="polite">Selecteer een datum op de kalender en vul hierboven je training in.</div><div class="wide"><button class="secondary" id="deleteSelectedTraining">Verwijder training van geselecteerde dag</button></div></div></div>`;
 const dateInput=$("trainingDate"),desc=$("trainingDescription"),status=$("calendarStatus");
 function loadDate(date){dateInput.value=date;const found=data.trainingDays.find(x=>x.date===date);desc.value=found?.training||'';status.textContent=found?'Training geregistreerd: '+found.training:(workoutDates.has(date)?'Je hebt op deze dag al een oefeningstraining opgeslagen. Je kunt hier ook een trainingsnaam toevoegen.':'Nog geen training geregistreerd voor deze dag.');}
 root.querySelectorAll('[data-calendar-date]').forEach(b=>b.onclick=()=>loadDate(b.dataset.calendarDate));
 dateInput.onchange=()=>{if(dateInput.value)loadDate(dateInput.value)};
 $('calendarPrev').onclick=()=>{calendarMonth=new Date(year,month-1,1);renderCalendar()};$('calendarNext').onclick=()=>{calendarMonth=new Date(year,month+1,1);renderCalendar()};
 $('saveTrainingDay').onclick=()=>{const date=dateInput.value,training=desc.value.trim();if(!date){status.textContent='Kies eerst een datum.';return}if(!training){status.textContent='Vul in wat je hebt getraind of gaat trainen.';return}const i=data.trainingDays.findIndex(x=>x.date===date);if(i>=0)data.trainingDays[i].training=training;else data.trainingDays.push({date,training});data.calendarHiddenWorkoutDates=(data.calendarHiddenWorkoutDates||[]).filter(d=>d!==date);persist();calendarMonth=new Date(date+'T12:00:00');renderCalendar();const updated=$('calendarStatus');if(updated)updated.textContent='✓ Training opgeslagen voor '+formatDate(date)+'.';};
 $('deleteSelectedTraining').onclick=()=>{const date=dateInput.value;if(!date){status.textContent='Selecteer eerst een datum.';return}data.trainingDays=data.trainingDays.filter(x=>x.date!==date);if(!Array.isArray(data.calendarHiddenWorkoutDates))data.calendarHiddenWorkoutDates=[];if(workoutDates.has(date)&&!data.calendarHiddenWorkoutDates.includes(date))data.calendarHiddenWorkoutDates.push(date);persist();renderCalendar();const refreshedDate=$("trainingDate"),refreshedStatus=$("calendarStatus"),refreshedDesc=$("trainingDescription");refreshedDate.value=date;refreshedDesc.value='';refreshedStatus.textContent='De kalendertraining voor '+formatDate(date)+' is verwijderd. Andere opgeslagen oefeningstrainingen blijven behouden.'};
}
function renderPhotos(){
 const root=$("photosView");
 const photos=[...(data.progressPhotos||[])].sort((a,b)=>b.date.localeCompare(a.date)||(a.createdAt||0)-(b.createdAt||0));
 const byDate=new Map();photos.forEach(ph=>{if(!byDate.has(ph.date))byDate.set(ph.date,[]);byDate.get(ph.date).push(ph)});
 const days=[...byDate.entries()];
 root.innerHTML=`<div class="panel"><div class="topline"><div><div class="eyebrow">Jouw transformatie</div><h2 class="selected-title">📸 Progressiefoto’s</h2><p class="muted">Foto’s van dezelfde datum staan samen in één diavoorstelling. Gebruik de pijltjes om tussen foto’s van die dag te wisselen. Klik op een foto om die groter te bekijken.</p></div></div><div class="note-card"><div class="note-title">➕ Nieuwe progressiefoto</div><form id="photoForm"><div class="photo-form"><div class="wide"><label for="progressPhotoFile">Foto’s kiezen of nemen (je kunt meerdere foto’s tegelijk selecteren)</label><input id="progressPhotoFile" type="file" accept="image/*" capture="environment" multiple required><img id="progressPhotoPreview" class="photo-preview" alt="Voorbeeld van je gekozen progressiefoto"><div id="photoSelectionInfo" class="muted" style="font-size:12px;margin-top:6px"></div></div><div><label for="progressPhotoDate">Datum</label><input id="progressPhotoDate" type="date" value="${new Date().toLocaleDateString('en-CA')}" required></div><div><label for="progressPhotoWeight">Gewicht (kg)</label><input id="progressPhotoWeight" type="number" min="0" max="500" step="0.1" placeholder="Bijv. 75,5"></div><div class="wide"><label for="progressPhotoNotes">Notities (optioneel)</label><textarea id="progressPhotoNotes" maxlength="1200" placeholder="Bijv. bicepsomtrek, hoe je je voelt, trainingsdoelen…"></textarea></div><div class="wide"><button class="primary full" type="submit">Foto opslaan</button><div class="notice">Foto's worden op dit toestel in deze browser bewaard. Kies bij voorkeur foto's die niet te groot zijn.</div><div id="photoFormStatus" class="toast" aria-live="polite"></div></div></div></form></div><h3 class="section-title">Jouw foto's (${photos.length}) · ${days.length} ${days.length===1?'datum':'datums'}</h3>${days.length?days.map(([date,dayPhotos],dayIndex)=>`<article class="day-slideshow" data-day-index="${dayIndex}"><img class="day-photo zoomable-progress-photo" src="${dayPhotos[0].image}" alt="Progressiefoto van ${esc(formatDate(date))} — klik om te vergroten" loading="lazy" tabindex="0" role="button" aria-label="Foto vergroten"><div class="slideshow-controls"><button class="secondary small" type="button" data-slide-prev="${dayIndex}" ${dayPhotos.length<2?'disabled':''}>← Vorige</button><span class="slide-position" data-slide-position="${dayIndex}">1 / ${dayPhotos.length}</span><button class="secondary small" type="button" data-slide-next="${dayIndex}" ${dayPhotos.length<2?'disabled':''}>Volgende →</button></div><div class="day-photo-info"><h3>${esc(formatDate(date))}</h3><div class="photo-meta">${dayPhotos[0].weight!==''&&dayPhotos[0].weight!=null?`<span>⚖️ ${esc(String(dayPhotos[0].weight))} kg</span>`:''}</div>${dayPhotos[0].notes?`<p>📝 ${esc(dayPhotos[0].notes)}</p>`:'<p class="muted">Geen notities toegevoegd.</p>'}<div class="photo-actions"><button class="secondary small" data-delete-photo="${esc(dayPhotos[0].id)}">Deze foto verwijderen</button></div></div></article>`).join(''):`<div class="empty-card">Je hebt nog geen progressiefoto's opgeslagen. Voeg je eerste foto toe om je vooruitgang bij te houden. 💗</div>`}</div>`;
 const fileInput=$("progressPhotoFile"), preview=$("progressPhotoPreview"), selectionInfo=$("photoSelectionInfo");
 fileInput.onchange=()=>{pendingPhotoData=[];preview.style.display='none';preview.removeAttribute('src');if(selectionInfo)selectionInfo.textContent='';const files=Array.from(fileInput.files||[]);if(!files.length)return;const status=$("photoFormStatus");let finished=0;const results=new Array(files.length);const finish=()=>{if(finished===files.length){pendingPhotoData=results.filter(Boolean);if(pendingPhotoData.length){preview.src=pendingPhotoData[0];preview.style.display='block';if(selectionInfo)selectionInfo.textContent=pendingPhotoData.length+' foto(’s) klaar om op te slaan.';}}};files.forEach((file,index)=>{if(!file.type.startsWith('image/')){finished++;if(status)status.textContent='Een geselecteerd bestand is geen afbeelding.';finish();return}const reader=new FileReader();reader.onload=()=>{const img=new Image();img.onload=()=>{const max=1200,scale=Math.min(1,max/Math.max(img.width,img.height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.width*scale));canvas.height=Math.max(1,Math.round(img.height*scale));const ctx=canvas.getContext('2d');ctx.drawImage(img,0,0,canvas.width,canvas.height);results[index]=canvas.toDataURL('image/jpeg',0.78);finished++;finish()};img.onerror=()=>{finished++;if(status)status.textContent='Een afbeelding kon niet worden geopend. Probeer die foto opnieuw.';finish()};img.src=reader.result};reader.onerror=()=>{finished++;if(status)status.textContent='Een bestand kon niet worden gelezen.';finish()};reader.readAsDataURL(file)});};
 $("photoForm").onsubmit=e=>{e.preventDefault();const status=$("photoFormStatus");if(!pendingPhotoData.length){status.textContent='Kies eerst één of meerdere foto’s en wacht tot het voorbeeld verschijnt.';return}const date=$("progressPhotoDate").value,weight=$("progressPhotoWeight").value.trim(),notes=$("progressPhotoNotes").value.trim();if(!date){status.textContent='Kies een datum.';return}const stamp=Date.now();const added=pendingPhotoData.map((image,i)=>({id:'photo'+stamp+'_'+i,image,date,weight,notes,createdAt:stamp+i}));data.progressPhotos.push(...added);try{persist();pendingPhotoData=[];renderPhotos()}catch(err){data.progressPhotos=data.progressPhotos.filter(ph=>!added.some(a=>a.id===ph.id));status.textContent='Er is onvoldoende lokale opslagruimte. Probeer kleinere foto’s of verwijder oude foto’s.';}};
 // Iedere datum heeft een eigen diavoorstelling; de pijlen wisselen alleen foto's binnen die datum.
 root.querySelectorAll('.day-slideshow').forEach(card=>{const dayIndex=Number(card.dataset.dayIndex),date=days[dayIndex][0],dayPhotos=days[dayIndex][1];let current=0;const image=card.querySelector('.day-photo'),position=card.querySelector('.slide-position'),info=card.querySelector('.day-photo-info');const show=()=>{const ph=dayPhotos[current];image.src=ph.image;image.alt='Progressiefoto van '+formatDate(date)+' — klik om te vergroten';position.textContent=(current+1)+' / '+dayPhotos.length;info.innerHTML=`<h3>${esc(formatDate(date))}</h3><div class="photo-meta">${ph.weight!==''&&ph.weight!=null?`<span>⚖️ ${esc(String(ph.weight))} kg</span>`:''}</div>${ph.notes?`<p>📝 ${esc(ph.notes)}</p>`:'<p class="muted">Geen notities toegevoegd.</p>'}<div class="photo-actions"><button class="secondary small" data-delete-photo="${esc(ph.id)}">Deze foto verwijderen</button></div>`;bindDelete(info.querySelector('[data-delete-photo]') );};card.querySelector('[data-slide-prev]').onclick=()=>{current=(current-1+dayPhotos.length)%dayPhotos.length;show()};card.querySelector('[data-slide-next]').onclick=()=>{current=(current+1)%dayPhotos.length;show()};const open=()=>{const lightbox=$("photoLightbox"),large=$("photoLightboxImage");large.src=image.src;lightbox.classList.add('open');document.body.style.overflow='hidden'};image.onclick=open;image.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();open()}};});
 function bindDelete(btn){if(btn)btn.onclick=()=>{if(confirm('Deze progressiefoto verwijderen?')){data.progressPhotos=data.progressPhotos.filter(ph=>ph.id!==btn.dataset.deletePhoto);persist();renderPhotos()}}}
 root.querySelectorAll('[data-delete-photo]').forEach(bindDelete);
}
function closePhotoLightbox(){const lightbox=$("photoLightbox");if(lightbox)lightbox.classList.remove('open');document.body.style.overflow='';} $("closePhotoLightbox").onclick=closePhotoLightbox; $("photoLightbox").addEventListener('click',e=>{if(e.target.id==='photoLightbox')closePhotoLightbox()});document.addEventListener('keydown',e=>{if(e.key==='Escape')closePhotoLightbox()});
function persist(){localStorage.setItem(KEY,JSON.stringify(data))}
function esc(s){return String(s).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
function exerciseById(id){return data.exercises.find(e=>e.id===id)}
function sessionsFor(id){return data.sessions.filter(s=>s.exerciseId===id).sort((a,b)=>b.date.localeCompare(a.date)||b.savedAt-a.savedAt)}
function formatDate(s){return new Date(s+"T12:00:00").toLocaleDateString("nl-BE",{day:"numeric",month:"short",year:"numeric"})}
function volume(sets){return sets.reduce((sum,s)=>sum+(Number(s.kg)||0)*(Number(s.reps)||0),0)}
function makeLineChart(sessions, metric, title, unit, color){
 const points=sessions.map(s=>({date:s.date,value:metric==='weight'?Math.max(0,...s.sets.map(x=>Number(x.kg)||0)):volume(s.sets)}));
 if(!points.length)return `<div class="chart-card"><div class="chart-title">${title}</div><div class="chart-subtitle">Je vooruitgang verschijnt zodra je trainingen opslaat.</div><div class="chart-empty">🐼 Nog geen gegevens om te tekenen. Sla je eerste training op!</div></div>`;
 const W=340,H=174,L=37,R=10,T=12,B=34, PW=W-L-R,PH=H-T-B;
 const vals=points.map(p=>p.value), lo=Math.min(0,...vals), hi=Math.max(...vals), span=(hi-lo)||1;
 const x=i=>L+(points.length===1?PW/2:i*PW/(points.length-1));
 const y=v=>T+PH-((v-lo)/span)*PH;
 const grid=[0,.25,.5,.75,1].map(f=>{let val=lo+span*f, yy=y(val);return `<line x1="${L}" y1="${yy}" x2="${W-R}" y2="${yy}" stroke="#53364f" stroke-width="1"/><text x="${L-6}" y="${yy+4}" fill="#d0a9c4" font-size="9" text-anchor="end">${Number(val.toFixed(1)).toLocaleString('nl-BE')}</text>`}).join('');
 const poly=points.map((p,i)=>`${x(i)},${y(p.value)}`).join(' ');
 const circles=points.map((p,i)=>`<circle cx="${x(i)}" cy="${y(p.value)}" r="3.5" fill="${color}" stroke="#fff0f9" stroke-width="1"><title>${formatDate(p.date)}: ${p.value.toLocaleString('nl-BE',{maximumFractionDigits:1})} ${unit}</title></circle>`).join('');
 const first=esc(new Date(points[0].date+'T12:00:00').toLocaleDateString('nl-BE',{day:'numeric',month:'short'}));
 const last=esc(new Date(points[points.length-1].date+'T12:00:00').toLocaleDateString('nl-BE',{day:'numeric',month:'short'}));
 const dateLabels=points.length===1?`<text x="${W/2}" y="${H-10}" fill="#d0a9c4" font-size="10" text-anchor="middle">${first}</text>`:`<text x="${L}" y="${H-10}" fill="#d0a9c4" font-size="10" text-anchor="start">${first}</text><text x="${W-R}" y="${H-10}" fill="#d0a9c4" font-size="10" text-anchor="end">${last}</text>`;
 return `<div class="chart-card"><div class="chart-title">${title}</div><div class="chart-subtitle">${points.length} ${points.length===1?'training':'trainingen'} · oudste naar nieuwste</div><svg class="chart-svg" viewBox="0 0 ${W} ${H}" role="img" aria-label="${title}">${grid}<polyline points="${poly}" fill="none" stroke="${color}" stroke-width="2.8" stroke-linecap="round" stroke-linejoin="round"/>${circles}${dateLabels}</svg><div class="chart-legend"><span><i class="chart-dot" style="background:${color}"></i>${metric==='weight'?'Hoogste gewicht':'Totaal volume'} (${unit})</span><span>Tip: tik op een punt voor datum en waarde.</span></div></div>`;
}
function renderProgressCharts(sessions){
 const chronological=[...sessions].sort((a,b)=>a.date.localeCompare(b.date)||(a.savedAt||0)-(b.savedAt||0));
 return `<div class="progress-section"><h3>🐼 Jouw progressie voor deze oefening</h3><div class="chart-grid">${makeLineChart(chronological,'weight','Zwaarste gewicht per training','kg','#ff4fa3')}${makeLineChart(chronological,'volume','Totaal trainingsvolume per training','kg','#ffb6dc')}</div></div>`;
}
function renderList(){
 const q=$("search").value.trim().toLowerCase();
 const list=data.exercises.filter(e=>(e.name+" "+e.group).toLowerCase().includes(q)).sort((a,b)=>a.name.localeCompare(b.name));
 $("exerciseList").innerHTML=list.length?list.map(e=>`<button class="exercise ${e.id===selectedId?"active":""}" data-id="${esc(e.id)}"><span>${esc(e.name)}<small>${esc(e.group||"Overig")}</small></span><span>›</span></button>`).join(""):`<div class="empty">Geen oefeningen gevonden.</div>`;
 $("exerciseList").querySelectorAll("[data-id]").forEach(b=>b.addEventListener("click",()=>{selectedId=b.dataset.id;loadWorkoutDraft(selectedId);editingSessionId=null;editingSessionDate=null;detailOpen=true;$("appLayout").classList.add("detail-mode");renderList();renderWorkout();window.scrollTo({top:0,behavior:"smooth"})}));
}
function renderWorkout(){
 const motivatorBanner=document.querySelector(".motivator-banner");if(motivatorBanner)motivatorBanner.style.display=detailOpen?"none":"";
 const e=exerciseById(selectedId), root=$("workout");
 if(!detailOpen){root.innerHTML=`<div class="topline"><div><div class="eyebrow">Training bijhouden</div><h2 class="selected-title">Kies een oefening</h2><p class="muted">Open een oefening uit de lijst om gewicht, reps, notities en grafieken overzichtelijk op één aparte pagina te zien.</p></div></div>`;return}
 if(!e){root.innerHTML='<div class="empty">Voeg een oefening toe om te beginnen.</div>';return}
 const sessions=sessionsFor(e.id), last=sessions[0];
 const latestSaved=[...data.sessions].sort((a,b)=>(b.savedAt||0)-(a.savedAt||0))[0];
 const canEditLast=!!last&&!!latestSaved&&latestSaved===last;
 const savedDraft=!draft.length?loadWorkoutDraft(e.id):null;if(!draft.length)draft=[{kg:"",reps:""},{kg:"",reps:""},{kg:"",reps:""}];
 const allSets=sessions.flatMap(s=>s.sets), bestKg=allSets.reduce((m,s)=>Math.max(m,Number(s.kg)||0),0);
 const bestVolume=allSets.reduce((m,s)=>Math.max(m,volume(s.sets||[])),0);
 root.innerHTML=`
 <div class="detail-heading"><button class="secondary back-button" id="backToExercises">← Alle oefeningen</button><div><div class="eyebrow">Oefening bekijken</div><span class="muted">${esc(e.group||"Overig")}</span></div></div><div class="topline"><div><h2 class="selected-title">${esc(e.name)}</h2></div><button class="secondary small" id="deleteExercise">Verwijder oefening</button></div>
 <div class="stats"><div class="stat"><span>Aantal trainingen</span><strong>${sessions.length}</strong></div><div class="stat"><span>Zwaarste gewicht</span><strong>${bestKg} <small style="font-size:11px">kg</small></strong></div><div class="stat"><span>Laatste sessie</span><strong style="font-size:14px">${last?esc(formatDate(last.date)):"—"}</strong></div></div>
 ${last?`<div class="previous"><strong>Vorige keer · ${esc(formatDate(last.date))}</strong><p>${last.sets.map((s,i)=>`Set ${i+1}: ${esc(s.kg)} kg × ${esc(s.reps)} reps`).join("　·　")}</p><p>Totaal volume: ${Math.round(volume(last.sets)).toLocaleString("nl-BE")} kg · ${last.sets.length} sets</p></div>`:`<div class="previous"><strong>Nog geen vorige training</strong><p>Vul hieronder je sets in. Je kunt ze bij je volgende training vergelijken.</p></div>`}
 <div class="rest-timer" aria-label="Rusttimer"><span class="timer-label">⏱ Rust</span><select id="restDuration" aria-label="Rustduur"><option value="90">1,5 min</option><option value="120">2 min</option><option value="150">2,5 min</option><option value="180">3 min</option></select><span class="rest-time" id="restTime">1:30</span><button type="button" class="timer-start" id="restStart">Start</button><button type="button" class="timer-reset" id="restReset">↺</button></div>
 <label for="sessionDate">Datum van de training</label><input id="sessionDate" type="date" value="${new Date().toLocaleDateString('en-CA')}">
 <div style="margin-top:17px" class="table-head"><span>Set</span><span>Gewicht (kg)</span><span>Reps</span><span></span></div>
 <div id="sets">${draft.map((s,i)=>`<div class="set-row"><div class="set-num">${i+1}</div><input type="number" min="0" step="0.5" inputmode="decimal" placeholder="kg" aria-label="Gewicht set ${i+1}" data-field="kg" data-index="${i}" value="${esc(s.kg)}"><input type="number" min="0" step="1" inputmode="numeric" placeholder="reps" aria-label="Herhalingen set ${i+1}" data-field="reps" data-index="${i}" value="${esc(s.reps)}"><button class="remove" data-remove="${i}" title="Verwijder set" aria-label="Verwijder set">×</button></div>`).join("")}</div>
 <div class="actions"><button class="secondary" id="addSet">+ Set toevoegen</button><button class="secondary" id="clearSets">Leegmaken</button></div>
 <div class="note-card"><div class="note-title">🐼 Jouw notities bij deze oefening</div><textarea id="exerciseNotes" maxlength="1500" placeholder="Bijv. Vandaag ging de oefening niet zo goed omdat mijn armen verzuurd waren door gisteren te trainen...">${esc(e.notes||"")}</textarea><div class="note-status" id="noteStatus">💗 Wordt automatisch opgeslagen</div></div>
 <div class="savebar">${canEditLast&&!editingSessionId?`<button class="secondary subtle-edit-button" id="editLastSession">✏️ Laatste training bewerken</button>`:""}<button class="primary" id="saveSession">${editingSessionId?"Wijzigingen opslaan":"Training opslaan"}</button></div><div class="toast" id="toast" aria-live="polite"></div>
 <div class="history"><h3>Trainingsgeschiedenis</h3>${sessions.length?sessions.map(s=>`<div class="history-item"><div class="history-date"><span>${esc(formatDate(s.date))}<span class="tag">${s.sets.length} sets</span></span><span>${Math.round(volume(s.sets)).toLocaleString("nl-BE")} kg volume</span></div><div class="history-detail">${s.sets.map((x,i)=>`Set ${i+1}: ${esc(x.kg)} kg × ${esc(x.reps)}`).join("　·　")}</div></div>`).join(""):'<p class="muted" style="font-size:13px">Je opgeslagen trainingen verschijnen hier.</p>'}</div>${renderProgressCharts(sessions)}`;
 bindRestTimer();
 if(editingSessionId&&editingSessionDate){$("sessionDate").value=editingSessionDate;}else if(savedDraft?.date){$("sessionDate").value=savedDraft.date;}
 const editLastButton=$("editLastSession");if(editLastButton)editLastButton.onclick=()=>{const target=[...data.sessions].sort((a,b)=>(b.savedAt||0)-(a.savedAt||0))[0];if(!target||target.exerciseId!==e.id)return;editingSessionId=target.savedAt;editingSessionDate=target.date;draft=target.sets.map(x=>({kg:String(x.kg),reps:String(x.reps)}));renderWorkout();window.scrollTo({top:0,behavior:"smooth"})};
 $("backToExercises").onclick=()=>{detailOpen=false;editingSessionId=null;editingSessionDate=null;$("appLayout").classList.remove("detail-mode");renderWorkout();window.scrollTo({top:0,behavior:"smooth"})};
 $("deleteExercise").onclick=()=>{if(confirm(`Oefening "${e.name}" en de bijbehorende geschiedenis verwijderen?`)){data.exercises=data.exercises.filter(x=>x.id!==e.id);data.sessions=data.sessions.filter(s=>s.exerciseId!==e.id);selectedId=data.exercises[0]?.id||null;draft=[];detailOpen=false;$("appLayout").classList.remove("detail-mode");persist();updateCoins();renderList();renderWorkout()}};
 $("sets").querySelectorAll("input").forEach(inp=>inp.addEventListener("input",()=>{draft[Number(inp.dataset.index)][inp.dataset.field]=inp.value;storeWorkoutDraft()}));
 $("sessionDate").addEventListener("input",storeWorkoutDraft);
 $("sets").querySelectorAll("[data-remove]").forEach(btn=>btn.addEventListener("click",()=>{if(draft.length<=1){alert("Laat minstens één set staan.");return}draft.splice(Number(btn.dataset.remove),1);storeWorkoutDraft();renderWorkout()}));
 $("addSet").onclick=()=>{draft.push({kg:"",reps:""});storeWorkoutDraft();renderWorkout();const inputs=$("sets").querySelectorAll("input");inputs[inputs.length-2]?.focus()};
 $("clearSets").onclick=()=>{draft=[{kg:"",reps:""},{kg:"",reps:""},{kg:"",reps:""}];storeWorkoutDraft();renderWorkout()};
 $("exerciseNotes").addEventListener("input",()=>{e.notes=$("exerciseNotes").value;persist();$("noteStatus").textContent="✓ Notities opgeslagen — volgende keer staan ze hier weer 💗"});
 $("saveSession").onclick=()=>{
   const sets=draft.map(s=>({kg:String(s.kg).trim(),reps:String(s.reps).trim()}));
   if(sets.some(s=>s.kg===""||s.reps==="")){$("toast").textContent="Vul voor elke set zowel gewicht als reps in.";return}
   if(sets.some(s=>Number(s.kg)<0||Number(s.reps)<0||!Number.isFinite(Number(s.kg))||!Number.isFinite(Number(s.reps)))){$("toast").textContent="Gebruik geldige, positieve getallen.";return}
   const date=$("sessionDate").value;if(!date){$("toast").textContent="Kies een datum.";return}
   if(editingSessionId){const index=data.sessions.findIndex(s=>s.savedAt===editingSessionId&&s.exerciseId===e.id);if(index<0){$("toast").textContent="Deze training kan niet meer worden bewerkt.";editingSessionId=null;editingSessionDate=null;return}data.sessions[index]={...data.sessions[index],date,sets};data.calendarHiddenWorkoutDates=(data.calendarHiddenWorkoutDates||[]).filter(d=>d!==date);persist();clearWorkoutDraft(e.id);editingSessionId=null;editingSessionDate=null;draft=[];renderWorkout();renderList();const toast=$("toast");if(toast)toast.textContent="✓ Laatste training aangepast.";}else{data.sessions.push({exerciseId:e.id,date,sets,savedAt:Date.now()});data.calendarHiddenWorkoutDates=(data.calendarHiddenWorkoutDates||[]).filter(d=>d!==date);data.coins=(Number(data.coins)||0)+1;persist();clearWorkoutDraft(e.id);updateCoins();renderShop();draft=[];renderWorkout();renderMotivator();const toast=$("toast");if(toast)toast.textContent="🐼 +1 muntje verdiend! Goed bezig!";}
 };
}
$("search").addEventListener("input",renderList);
$("addExercise").onclick=()=>{const name=$("newExercise").value.trim();if(!name){$("newExercise").focus();return}if(data.exercises.some(e=>e.name.toLowerCase()===name.toLowerCase())){alert("Deze oefening bestaat al.");return}const e={id:"e"+Date.now(),name,group:$("newGroup").value};data.exercises.push(e);selectedId=e.id;draft=[];detailOpen=true;$("appLayout").classList.add("detail-mode");$("newExercise").value="";$("search").value="";persist();renderList();renderWorkout();switchTab("exercises")};
document.querySelectorAll(".tab-btn").forEach(b=>b.addEventListener("click",()=>switchTab(b.dataset.tab)));$("openSettings").onclick=()=>switchTab("settings");const motivatorBanner=document.querySelector(".motivator-banner");if(motivatorBanner){motivatorBanner.setAttribute("role","button");motivatorBanner.setAttribute("tabindex","0");motivatorBanner.setAttribute("aria-label","Open de trainingskalender");motivatorBanner.addEventListener("click",()=>switchTab("calendar"));motivatorBanner.addEventListener("keydown",e=>{if(e.key==="Enter"||e.key===" "){e.preventDefault();switchTab("calendar")}})}
renderList();renderWorkout();updateCoins();renderShop();renderMotivator();
// Voorkom pinch/dubbel-tik-zoom in browsers die deze gebaren aanbieden.
document.addEventListener("gesturestart",e=>e.preventDefault(),{passive:false});
document.addEventListener("gesturechange",e=>e.preventDefault(),{passive:false});
document.addEventListener("gestureend",e=>e.preventDefault(),{passive:false});
let lastTouchEnd=0;document.addEventListener("touchend",e=>{const now=Date.now();if(now-lastTouchEnd<=300)e.preventDefault();lastTouchEnd=now;},{passive:false});

if ("serviceWorker" in navigator && (location.protocol === "https:" || location.hostname === "localhost")) { window.addEventListener("load", () => navigator.serviceWorker.register("./sw.js").catch(() => {})); }
$("closeCharacterPreview").addEventListener("click",closeCharacterPreview);$("characterPreview").addEventListener("click",e=>{if(e.target.id==="characterPreview")closeCharacterPreview()});document.addEventListener("keydown",e=>{if(e.key==="Escape")closeCharacterPreview()});